namespace Gordic.Ada.WebClient {
    var gcontent = Decorators.gcontent;

    @gcontent
    export class GSestavyAda extends GContentBase {

        private sesTreeParams;
        private sestava: Report.Interface.GReportInfoDto;
        private wrid: string;

        private rok_akt: number;
        private mesic_akt: number;

        private readonly globals: Gordic.Ada.WebClient.DTO.GAdaGlobalsDto;

        title = "Sestavy";
        taskId = "actSestavyAda"; // označení položky v taskListu

        onContentReady() {

            var that = this;
            var $tab = $(this.contentDiv);

            $tab.empty();

            var cnt = this;

            var mainForm = $("<div>").appendTo(this.element).gform("setup", { layoutDescriptor: "L1M1S1 LMS-0-12-0" }).gformsection("create");

            //nastavení akcí
            cnt.actions.addRange({
                actClose: {
                    caption: "Zrušit",
                    run: function () {
                        that.tryClose();
                    }
                },
                actTisk: {
                    caption: "Generovat",
                    run: function () {
                        if (cnt.sestava) {
                            that.generovat();
                        }
                    }
                }

            //var actEdit = new GAction({
            //    name: "dblclick",
            //    run: function (ev, ctx) {
            //        GDlg.alert("Dvojklik");
            //        // ctx.cellInfo.data
            //    }
            //});
            });

            cnt.menuBar(this.actions.createBar(["actTisk*"]));
            cnt.commandBar(this.actions.createBar(["actClose"]));

            mainForm
                .appendTo(this.element)
                .gcontent(Gordic.Report.WebClient.GReportTreeControlTS, { controlParams: this.sesTreeParams.ControlParams });

            mainForm.on({
                "reportselected.greports": function (event, output) {
                    if (!output || !output.reportId)
                        return;

                    console.log("GOdtPozadavekControl on reportselected.greports", event, output);
                    that.beginOperation();
                    that.wrid = output.reportId;

                    Gordic.Report.WebClient.GReportTreeControlTS.getReportInfo(output.reportId, that.sesTreeParams.ControlParams.Platnost)
                        .then(function (ri) {
                            if (ri && ri.alv)
                                cnt.sestava = ri;
                                console.log("ri", ri.alv!.TYP_ALG);
                        })
                        .always(function () { that.endOperation(); });
                    }
            });

            mainForm.gtab({
                title: "Výběr sestavy",
                opened: true,
//                menuBar: $.content(mainForm).getMenuDef()
            });


            //var actEdit = new GAction({
            //    name: "dblclick",
            //    run: function (ev, ctx) {
            //        GDlg.alert("Dvojklik");
            //        // ctx.cellInfo.data
            //    }
            //});


            var $mainTable = $("<div>")
                //.css("height", "100%")
                .appendTo(mainForm)
//                .gautofit()
                ;

        }

        generovat() {
            var that = this;
            var cnt = this;

            var Form_Maska: Gordic.Forms.Form;

            Form_Maska = new Gordic.Forms.Form(
                {
                    name: "maskaFormular",
                    layoutDescriptor: "L1M1S1 M-3-9-0 L-3-9-0 breaks-400-500",
                    dialogOptions: {
                        id: "MaskaFormular#"
                    } as any
                    ,
                    complete: function (a) {
                        //debugger;
                        console.log("xxx");
                    }
                });

            Form_Maska
            //.addField("gdummyfield", "w-h", {
            //    model: "maska",
            //    name: "maska"
            //})
            .addField("gstringbox", "w-h", {
                model: "maska",
                name: "maska",
                change(ev, selected) {
                    if ((selected) && (selected.value)) {
                        var form = $(this).closest(".gform");
                        var in_maska = selected.value;
                        if (in_maska.charAt(0) !== "1") {
                            form.findFields("stavbaStart").gfield("disable");
                            form.findFields("stavbaEnd").gfield("disable");
                        }
                        if (in_maska.charAt(1) !== "1") {
                            form.findFields("objektStart").gfield("disable");
                            form.findFields("objektEnd").gfield("disable");
                        }
                        if (in_maska.charAt(2) !== "1") {
                            form.findFields("mandatarStart").gfield("disable");
                            form.findFields("mandatarEnd").gfield("disable");
                        }
                        if (in_maska.charAt(3) !== "1") {
                            form.findFields("ueaStart").gfield("disable");
                            form.findFields("ueaEnd").gfield("disable");
                        }
                        if (in_maska.charAt(4) !== "1") {
                            form.findFields("uebStart").gfield("disable");
                            form.findFields("uebEnd").gfield("disable");
                        }
                        if (in_maska.charAt(5) !== "1") {
                            form.findFields("inv_cisStart").gfield("disable");
                            form.findFields("inv_cisEnd").gfield("disable");
                        }
                        if (in_maska.charAt(6) !== "1") {
                            form.findFields("priz_nulove").gfield("disable");
                        }

                    }
                }
            })

            Form_Maska
                .addRow("Organizace").addField("gselectbox", Gordic.Prefabs.Select.ekosrar(), {
                    name: "nks",
                    model: "model.ixs_rar=value.ixs_rar;model.nks=value.ico;model.nks_txt=value.nazev",
                })

            Form_Maska
                .addRow("Rok/Měsíc")
                    .addField("gnumberbox", "w-4", { name: "rok", disabled: true })
                    .addField("gnumberbox", "w-4", { name: "mesic", validators: [new Gordic.Validators.Required(), new Gordic.Validators.Range({ min: 1, max: 12, message: "Chybně zadaná hodnota" })] })

            Form_Maska
                .addSection("")
                .addPrefab(Gordic.Gin.Prefabs.interval({
                    type: "string", label: "Stavba", name: "stavba", pathInModel: "stavba",
                    customOptFieldStart: Eko.Detail.Field.getCounterOptions(that.globals.Delka_Akce!, true, true),
                    customOptFieldEnd: Eko.Detail.Field.getCounterOptions(that.globals.Delka_Akce!, true, true),
                    customOptAll: {

                        change: function (ev, changeObj) {
                            if (changeObj.flags.noChange) {
                                return;
                            }

                            var hodnota: string;
                            hodnota = changeObj.value;
                            if ((hodnota) && (hodnota.length < that.globals.Delka_Akce!)) {
                                $(this).gfield("setValue", Utils.zeropad(hodnota, that.globals.Delka_Akce!));
                            }
                        }
                    }
                }));

            Form_Maska
                .addPrefab(Gordic.Gin.Prefabs.interval({
                    type: "string", label: "Objekt", name: "objekt", pathInModel: "objekt",
                    customOptFieldStart: Eko.Detail.Field.getCounterOptions(4, true, true),
                    customOptFieldEnd: Eko.Detail.Field.getCounterOptions(4, true, true),
                }));

            Form_Maska
                .addPrefab(Gordic.Gin.Prefabs.interval({
                    type: "string", label: "Mandatář", name: "mandatar", pathInModel: "mandatar",
                    customOptFieldStart: Eko.Detail.Field.getCounterOptions(3, true, true),
                    customOptFieldEnd: Eko.Detail.Field.getCounterOptions(3, true, true),
                }));

            Form_Maska
                .addPrefab(Gordic.Gin.Prefabs.interval({
                    type: "string", label: "SU", name: "uea", pathInModel: "uea",
                    customOptFieldStart: Eko.Detail.Field.getCounterOptions(3, true, true),
                    customOptFieldEnd: Eko.Detail.Field.getCounterOptions(3, true, true),
                }));

            Form_Maska
                .addPrefab(Gordic.Gin.Prefabs.interval({
                    type: "string", label: "AU", name: "ueb", pathInModel: "ueb",
                    customOptFieldStart: Eko.Detail.Field.getCounterOptions(4, true, true),
                    customOptFieldEnd: Eko.Detail.Field.getCounterOptions(4, true, true),
                }));

            Form_Maska
                .addPrefab(Gordic.Gin.Prefabs.interval({
                    type: "string", label: "Inventární číslo", name: "inv_cis", pathInModel: "inv_cis",
                    customOptFieldStart: Eko.Detail.Field.getCounterOptions(4, true, true),
                    customOptFieldEnd: Eko.Detail.Field.getCounterOptions(4, true, true),
                }));

            Form_Maska
                .addRow("Nezobrazit nulové stavby").addField("gcheck", "w-12", {
                    disabled: false, name: "priz_nulove", modelValueTransform: {
                        apply: (v) => {
                            return v == 1;
                        },
                        collect: (v) => {
                            return (v ? 1 : 0);
                        }
                    }
                });


            var radekMaska: {
                maska: string,
                nks: string,
                rok: number,
                mesic: number,
                priz_nulove: number,
                stavba: { start: string, end: string },
                objekt: { start: string, end: string },
                mandatar: { start: string, end: string },
                uea: { start: string, end: string },
                ueb: { start: string, end: string },
                inv_cis: { start: string, end: string }
            } = {
                maska: "",
                nks: "",
                rok: 0,
                mesic: 0,
                priz_nulove: 0,
                stavba: { start: "", end: "" },
                objekt: { start: "", end: "" },
                mandatar: { start: "", end: "" },
                uea: { start: "", end: "" },
                ueb: { start: "", end: "" },
                inv_cis: { start: "", end: "" }
            };

            radekMaska.maska = cnt.sestava.alv!.TYP_ALG;
            radekMaska.rok = cnt.rok_akt;
            radekMaska.mesic = cnt.mesic_akt;

            let prom_vysledek = cnt.dialogs.simpleForm("Maska pro generování sestavy", Form_Maska, radekMaska , { width: 700, height: 500 });
            let prom_vysledek_pro = prom_vysledek.createDialogPromise( /*"close"*//*"yes"*//*"ok"*//*, { duvod: string }*/)
                .then(function (data) {
                    if (data) {
                        radekMaska = data;
                        if (radekMaska.maska.charAt(0) !== "1") {
                        //    radekMaska.stavba.start = "";
                        //    radekMaska.stavba.end = "";
                        }
                        else { 
                            radekMaska.stavba.start = radekMaska.stavba.start ? Utils.zeropad(radekMaska.stavba.start, that.globals.Delka_Akce!) : Utils.zeropad("0", that.globals.Delka_Akce!);
                            radekMaska.stavba.end = radekMaska.stavba.end ? Utils.zeropad(radekMaska.stavba.end, that.globals.Delka_Akce!) : Utils.zeropad("0", that.globals.Delka_Akce!).replace(/0/g, "9");
                        }
                        if (radekMaska.maska.charAt(1) !== "1") {
                        //    radekMaska.objekt.start = "";
                        //    radekMaska.objekt.end = "";
                        }
                        else { 
                            radekMaska.objekt.start = radekMaska.objekt.start ? Utils.zeropad(radekMaska.objekt.start, 4) : Utils.zeropad("0", 4);
                            radekMaska.objekt.end = radekMaska.objekt.end ? Utils.zeropad(radekMaska.objekt.end, 4) : Utils.zeropad("0", 4).replace(/0/g, "9");
                        }
                        if (radekMaska.maska.charAt(2) !== "1") {
                        //    radekMaska.mandatar.start = "";
                        //    radekMaska.mandatar.end = "";
                        }
                        else { 
                            radekMaska.mandatar.start = radekMaska.mandatar.start ? Utils.zeropad(radekMaska.mandatar.start, 3) : Utils.zeropad("0", 3);
                            radekMaska.mandatar.end = radekMaska.mandatar.end ? Utils.zeropad(radekMaska.mandatar.end, 3) : Utils.zeropad("0", 3).replace(/0/g, "9");
                        }
                        if (radekMaska.maska.charAt(3) !== "1") {
                        //    radekMaska.uea.start = "";
                        //    radekMaska.uea.end = "";
                        }
                        else { 
                            radekMaska.uea.start = radekMaska.uea.start ? Utils.zeropad(radekMaska.uea.start, 3) : Utils.zeropad("0", 3);
                            radekMaska.uea.end = radekMaska.uea.end ? Utils.zeropad(radekMaska.uea.end, 3) : Utils.zeropad("0", 3).replace(/0/g, "9");
                        }
                        if (radekMaska.maska.charAt(4) !== "1") {
                        //    radekMaska.ueb.start = "";
                        //    radekMaska.ueb.end = "";
                        }
                        else { 
                            radekMaska.ueb.start = radekMaska.ueb.start ? Utils.zeropad(radekMaska.ueb.start, 4) : Utils.zeropad("0", 4);
                            radekMaska.ueb.end = radekMaska.ueb.end ? Utils.zeropad(radekMaska.ueb.end, 4) : Utils.zeropad("0", 4).replace(/0/g, "9");
                        }
                        if (radekMaska.maska.charAt(5) !== "1") {
                        //    radekMaska.inv_cis.start = "";
                        //    radekMaska.inv_cis.end = "";
                        }
                        else {
                            radekMaska.inv_cis.start = radekMaska.inv_cis.start ? Utils.zeropad(radekMaska.inv_cis.start, 10) : Utils.zeropad("0", 10);
                            radekMaska.inv_cis.end = radekMaska.inv_cis.end ? Utils.zeropad(radekMaska.inv_cis.end, 10) : Utils.zeropad("0", 10).replace(/0/g, "9");;
                        }

                        console.log("radekMaska", radekMaska);
                        var cancellationToken = {
                            cancel: false
                        };
                        let _currGeneratingDef = $.Deferred();

                        var generator: Report.WebClient.GReportGenerator;

                        generator = new Report.WebClient.GReportGenerator({
                            // reportGeneratorType: "Gordic.Odt.WebClient.GOdtPozadavekGenerator",
                            waitToAsync: 1
                        });

                        Report.WebClient.GReportGenerator.progressBegin(
                            that,
                            new GAction({
                                name: "repGenCancelAct",
                                caption: "Storno",
                                run: function () {
                                    cancellationToken.cancel = true;
                                    this.update({
                                        caption: "Stornuji",
                                        enabled: false
                                    });
                                }
                            }));

                        var platnost = that.sesTreeParams.ControlParams.Platnost;

                        generator.generate({
                            reportId: that.wrid,
                            outputStyle: that.sestava.alv!.OutputStyle,
                            platnost: platnost,
                            customDto: radekMaska,
                            serverParameterMethod: "Gordic.Ada.WebClient.GSestavyAda:ConvertReportParams",
                            //                generatorParams: null,
                            props: {
                                Platnost: platnost,
                            }
                        },
                            null,
                            cancellationToken)
                            .progress(function (progress) {
                                Report.WebClient.GReportGenerator.progressUpdate(that, progress);
                            })
                            .then(function (res) {
                                var document = new Report.WebClient.GReportDocument(that);
                                return document.downloadDocument(Gordic.Report.WebClient.GReportTreeControlTS.getDownloaderParams(res));

                                //NOTE: Dela problem na IE - activeX ho lokalne vytvori pod jinym nazvem nez je pozadovany
                                //document.downloadDocument(Gordic.Report.WebClient.GReportTreeControlTS.getDownloadOnlyParams(res.id)); 
                            })
                            .fail(function (state) {
                                if (state && state.id) {
                                    var document = new Report.WebClient.GReportDocument(that);
                                    document.downloadDocument({
                                        DownloaderType: "Gordic.Report.WebClient.Reporter.SinglePage.Common.GReportDownloader",
                                        AutoDownload: true,
                                        CustomData: { "id": state.id }
                                    });
                                }
                                else if (state && $.isPlainObject(state) && state.state === -2) { //-2 = generovani zruseno uzivatelem
                                    that.showFlash({
                                        label: "Generování sestavy bylo zrušeno uživatelem",
                                        customClass: "g-state-warning"
                                    });
                                }
                            })
                            .always(function () {
                                that.endOperation();
                                _currGeneratingDef.resolve();
                            });
                    }
                    }
                );
        }
    }
}
